  "interactiveHelp.title": "Interaktive Hilfe",
  "interactiveHelp.subtitle": "Klicke etwas an, um darüber zu lesen",
  "interactiveHelp.named": "„{name}“",
  "interactiveHelp.close": "Hilfefenster schließen",
  "interactiveHelp.nothing": "Hier gibt es nichts zu erklären. Zeige auf einen Knopf, ein Feld, einen Griff oder ein Fenster.",
  "interactiveHelp.loading": "Wird in der Anleitung nachgeschlagen ...",
  "interactiveHelp.noIndex": "Die Anleitung ist hier noch nicht verfügbar. Öffne sie über die Übersicht.",
  "interactiveHelp.panelOnly": "Dieser Teil hat keinen eigenen Namen. Das Fragezeichen seines Fensters öffnet den Teil der Anleitung dazu.",
  "interactiveHelp.sectionOnly": "Zu diesem Teil gibt es einen Abschnitt in der Anleitung.",
