  "interactiveHelp.open": "In der Anleitung öffnen",
  "interactiveHelp.started": "Interaktive Hilfe ist an: Klicke einen Knopf, ein Feld oder ein Fenster an, um darüber zu lesen. Esc beendet sie.",
  "interactiveHelp.ended": "Interaktive Hilfe ist aus",
  "shortcuts.interactiveHelp": "Interaktive Hilfe ein- oder ausschalten",
  "installHint.chromium": "Installieren über das Symbol rechts in der Adressleiste oder im Browsermenü unter „Als App installieren“.",
  "installHint.safariMac": "In Safari: Menü „Ablage“ → „Zum Dock hinzufügen“.",
  "installHint.ios": "In Safari: Teilen-Symbol → „Zum Home-Bildschirm“.",
  "installHint.firefox": "Firefox kann keine Apps installieren – offline startet layerling hier trotzdem im Tab.",
  "welcome.moreLanguagesTitle": "Deine Sprache",
  "welcome.moreLanguagesBody": "das Programm und seine Anleitung gibt es auf Englisch, Deutsch und in 17 weiteren Sprachen; die Sprachliste steht ganz oben rechts und in den Einstellungen auf der Startseite.",
  "welcome.moreOfflineTitle": "Ohne Internet",
  "welcome.moreOfflineBody": "nach dem ersten Besuch startet layerling auch offline - installiert wie ein normales Programm, die Entwürfe bleiben auf deinem Rechner.",
  "welcome.moreAiTitle": "Mit KI bauen",
  "welcome.moreAiBody": "Über die MCP-Schnittstelle kann ein KI-Assistent Formen anlegen und bearbeiten, in einem Editor, den er selbst öffnet. Das braucht eine Kopie, die du selbst betreibst (npm run dev oder das Docker-Image); auf layerling.com ist die KI-Anbindung aus.",
  "welcome.morePointsTitle": "Bezugspunkte",
  "welcome.moreSearchTitle": "Befehlssuche",
  "welcome.moreSimplifyTitle": "Netze vereinfachen",
  "welcome.moreSimplifyBody": "Ein importiertes Netz mit sehr vielen Dreiecken wird auf einen Bruchteil verkleinert, mit Vorher-Nachher-Ansicht und Regler - damit Schneiden, Gruppieren und Ziehen flüssig bleiben.",
  "welcome.moreHistoryTitle": "Verlauf",
  "welcome.moreLookTitle": "Darstellung nach Wunsch",
  "welcome.moreLookBody": "Hintergrund und Arbeitsebene, Achsenpfeile für X, Y und Z, Kantenlinien an allen Körpern, die Farben der Skizze sowie Kontrast, Schatten und die Richtung des Lichts stellst du in den Einstellungen selbst ein - zum Beispiel, damit dunkle Körper nicht ineinander verschwimmen. Auf langsameren Rechnern schaltet der Schnellmodus alles Aufwendige auf einmal ab.",
  "welcome.moreHistoryBody": "mit einem Schieber auf jeden früheren Stand des Projekts zurückschauen, ohne etwas zu ändern - diesen Stand exportieren, als neues Projekt anlegen oder einzelne Objekte daraus zurückholen.",
  "welcome.moreDrawingTitle": "Zeichnung für die Werkstatt",
  "welcome.moreDrawingBody": "Exportieren → Zeichnung: Vorder-, Drauf- und Seitenansicht im Maßstab 1:1 auf einem ISO-Blatt, mit Gesamtmaßen, verdeckten Kanten und einer Tabelle der runden Bohrungen – als PDF oder SVG, zum Ausdrucken oder für Drehbank und Fräse. Die Draufsicht als SVG oder DXF geht an den Laserschneider, auf Wunsch mit Stegen wie bei einer Schablone, die die Mitte eines o oder b halten.",
  "welcome.moreSearchBody": "Mit Strg+K tippst du den Namen eines Werkzeugs, einer Form oder eines Befehls und springst direkt dorthin - auch auf Englisch, mit allen Tastenkürzeln daneben. Auch die Körper deines Entwurfs findest du mit ihrem Namen.",
  "welcome.morePointsBody": "Körper mit der rechten Maustaste anklicken und Mitte, Ecken oder Kantenmitten mit Punkten markieren, die nichts druckt und an denen Formen einrasten - so setzt du ein Loch genau auf die Mitte eines anderen Teils.",
  "welcome.videosTitle": "Videos über layerling",
  "welcome.videosHint": "Von anderen gemacht, nicht von diesem Projekt. Die Links öffnen YouTube in einem neuen Tab; von dort wird erst etwas geladen, wenn du klickst.",
  "welcome.help": "Im Editor findest du im Bereich Hilfe eine Kurzanleitung und die Übersicht aller Tastenkürzel. Unten in der Fußzeile speichert „Fehlerbericht“ deinen Entwurf samt den nötigen Angaben für eine Meldung im Forum oder bei GitHub.",
  "welcome.guideLink": "Die ausführliche Anleitung mit Bildern lesen",
  "welcome.guideUrl": "/anleitung/index.html",
  "guide.helpLink": "Dazu in der Anleitung nachlesen",
