  "guide.edges.offset": "Versatz verschiebt jede Fläche eines Körpers um dieselbe Strecke, nach außen oder innen. Vergrößere eine Kopie und behalte sie als Loch, so bekommst du das Spiel einer Passung; oder verkleinere einen Körper für einen Zapfen, der in ein Loch passen soll. Körper, die nur ein Dreiecksnetz sind, lassen sich oft nicht versetzen.",
