  "status.onlyOnePart": "Das gewählte Objekt besteht nur aus einem zusammenhängenden Teil",
  "status.meshTooDense": "Dieses Netz hat {triangles} Dreiecke. Die Kantenbearbeitung schafft {limit}; darüber rechnet der Kern länger, als jede Wartezeit hergibt. Bei einer Form aus der Formenliste geht es vorerst nur über ihre eigenen Einstellungen. Ein importiertes Teil liest du besser als STEP ein oder speicherst es vorher mit weniger Dreiecken.",
  "status.meshDenseAsk": "Dieses Netz hat {triangles} Dreiecke, mehr als die {limit}, für die die Kantenbearbeitung gebaut ist. Darüber kann es viele Minuten dauern, die Seite kann einfrieren, und alles Ungespeicherte geht verloren, wenn du sie schließen musst. Speichere dein Design vorher.\n\nTrotzdem versuchen?",
  "status.threadTooDense": "Ein Gewinde besteht aus {triangles} Dreiecken — zu viele für die Kantenbearbeitung, die bei {limit} aufhört. Setze das Gewinde deshalb erst nach der Kantenbearbeitung ein: erst Fase oder Verrundung am Körper, dann das Gewinde. Die Kopffase in den Eigenschaften bricht die Kante des Schraubenkopfs ohne diesen Umweg.",
  "status.unlockImageDelete": "Entsperre das Skizzenbild mit L, bevor du es löschst",
  "status.unlockImageEdit": "Entsperre das Skizzenbild mit L, bevor du es bearbeitest",
  "status.updatingRevolve": "Rotationsvorschau wird aktualisiert …",
  "status.waitForPreview": "Warte auf eine gültige Kantenvorschau, bevor du anwendest",
  "status.deletedOne": "1 Form gelöscht",
  "status.deletedMany": "{count} Formen gelöscht",
  "status.cutTooComplex": "Diese Geometrie ist zum Ausschneiden zu komplex: {triangles} Dreiecke, die Grenze liegt bei {limit}. Vereinfache (dezimiere) das Netz zuerst oder erhöhe die Grenze in den Arbeitsbereich-Einstellungen.",
  "status.groupNotMerged": "Gruppiert, aber nicht zu einem Körper vereinigt: Die Teile haben zusammen {triangles} Dreiecke, mehr als die Grenze von {limit}. Ein Export behält sie überlappend, und Slicer melden das als Fehler (nicht-mannigfaltige Kanten). Erhöhe die Grenze in den Arbeitsbereich-Einstellungen oder vereinfache das Netz und gruppiere dann erneut.",
  "status.cutNotWatertightTooComplex": "Dieses Netz ist nicht wasserdicht und mit {triangles} Dreiecken zu komplex für den Ersatzschnitt (Grenze {limit}). Repariere oder vereinfache (dezimiere) das Netz zuerst.",
  "status.cutOne": "1 Form ausgeschnitten",
