  "prop.threadCoreDiameter": "Kerndurchmesser",
  "thread.flankAngleHint": "Der Winkel zwischen den beiden Flanken eines Zahns. 60° ist das spitze Gewinde, 30° das Trapezgewinde. Bei 90° oder weniger ist keine Flanke flacher als 45°, das Gewinde druckt also ohne Stützen.",
  "thread.axialClearanceHint": "Zusätzliches Spiel längs des Gewindes in mm, zusätzlich zum Spiel: Jeder Zahn der Mutter wird um diesen Wert dünner, der Durchmesser bleibt. Für ein leichtgängiges Gewinde, das seitlich nicht wackelt: das Spiel bei etwa 0,2 bis 0,3 lassen und hier 0,2 einstellen. Bei 0 kommt das Spiel nur vom Spiel im Durchmesser, das die Flanken nur etwa halb so weit öffnet.",
  "thread.clearanceHint": "Das zusätzliche Spiel über den ganzen Durchmesser. Ein gedrucktes Gewinde braucht mehr, als man denkt: Der Spalt zwischen den Flanken ist nur etwa halb so groß. Um 0,3 ist eng, 0,4 üblich, 0,5 locker. Drucke zuerst ein Testpaar.",
  "thread.boltClearanceHint": "Macht den Bolzen um diesen Wert dünner, für eine Metallmutter, die selbst kein Spiel hat (0,3 bis 0,4, so viel wie eine gedruckte Mutter hätte). Bei einer gedruckten Mutter bleibt es 0, und die Mutter bekommt das Spiel.",
