  "prop.hingeScrewSpacing": "Lochabstand (längs)",
  "prop.hingeScrewSpacingHint": "Von Lochmitte zu Lochmitte entlang der Achse. 0 verteilt die Löcher gleichmäßig über die Länge.",
  "prop.hingeScrewAcross": "Lochabstand (quer)",
  "prop.hingeScrewAcrossHint": "Vom Loch im einen Blatt zum Loch im anderen, Mitte zu Mitte. 0 setzt jedes Loch in die Mitte seines Blatts.",
  "prop.gridfinityType": "Art",
  "gridfinity.bin": "Behälter",
  "gridfinity.baseplate": "Bodenplatte",
  "gridfinity.binHint": "Ein Behälter im 42-mm-Raster von Gridfinity: Er steht in einer Bodenplatte und lässt sich auf andere Behälter stapeln, auch auf solche aus anderen Gridfinity-Generatoren.",
  "gridfinity.baseplateHint": "Die Platte, in der Gridfinity-Behälter stehen, 5 mm hoch: eine Mulde für jede Rastereinheit von 42 mm.",
  "gridfinity.tray": "Schale",
  "gridfinity.trayHint": "Eine Schale beliebiger Größe in mm mit flachem Boden, für Spieleinsätze und Kleinteile: ohne Füße und ohne Stapelrand, sie steht also in keiner Bodenplatte und lässt sich nicht stapeln. Ihre Trennwände und Etikettenleisten reichen bis oben.",
  "prop.gridfinityUnitsX": "Einheiten breit",
  "prop.gridfinityUnitsZ": "Einheiten tief",
  "prop.gridfinityUnitsY": "Einheiten hoch",
  "prop.gridfinityLip": "Stapelrand",
  "prop.gridfinityLipChamfer": "Fase am Stapelrand",
  "gridfinity.lipChamferHint": "Versieht die obere Kante des Stapelrands mit einer Fase; bei 0 bleibt sie scharf, wie die Gridfinity-Spezifikation sie zeichnet.",
  "prop.gridfinityMagnets": "Magnetlöcher",
  "prop.gridfinityHalfGrid": "Halbes Raster (21 mm)",
  "gridfinity.halfGridHint": "Einheiten breit und tief zählen Zellen von 21 mm, jede mit einem eigenen Fuß; vier stehen in einer Mulde der Bodenplatte.",
  "prop.gridfinityFloorHeight": "Bodenhöhe",
  "gridfinity.floorHeightHint": "Bis zu dieser Höhe, von der Unterseite an gemessen, ist der Behälter massiv: ein Rohling, in den du Formen schneidest.",
  "prop.gridfinityWallThickness": "Wandstärke",
  "gridfinity.wallThicknessHint": "Die Wand wird von außen nach innen gemessen; die Außenseite bleibt, wie sie ist. Mit Stapelrand endet eine Wand von mehr als 1,75 mm an einem Absatz 0,85 mm unter 7 mm je Höheneinheit, mit Abstand zu den Füßen eines darauf gestapelten Behälters.",
  "prop.gridfinityOpenBack": "Hinten offen",
  "prop.gridfinityOpenFront": "Vorne offen",
  "prop.gridfinityOpenLeft": "Links offen",
  "prop.gridfinityOpenRight": "Rechts offen",
  "prop.gridfinityOpeningDepthBack": "Tiefe hinten",
  "prop.gridfinityOpeningDepthFront": "Tiefe vorne",
  "prop.gridfinityOpeningDepthLeft": "Tiefe links",
  "prop.gridfinityOpeningDepthRight": "Tiefe rechts",
  "prop.gridfinityOpeningWidthBack": "Breite hinten",
  "prop.gridfinityOpeningWidthFront": "Breite vorne",
  "prop.gridfinityOpeningWidthLeft": "Breite links",
  "prop.gridfinityOpeningWidthRight": "Breite rechts",
  "prop.gridfinityOpeningPositionBack": "Position hinten",
  "prop.gridfinityOpeningPositionFront": "Position vorne",
  "prop.gridfinityOpeningPositionLeft": "Position links",
  "prop.gridfinityOpeningPositionRight": "Position rechts",
  "prop.gridfinityOpeningDistanceBack": "Abstand hinten",
  "prop.gridfinityOpeningDistanceFront": "Abstand vorne",
  "prop.gridfinityOpeningDistanceLeft": "Abstand links",
  "prop.gridfinityOpeningDistanceRight": "Abstand rechts",
  "gridfinity.openingHint": "Die Tiefe wird von der Oberkante des Stapelrands gemessen (ohne Stapelrand von der Oberkante des Behälters), der Abstand von dem Ende, an das die Öffnung gesetzt ist. Über die ganze Breite bis zum Boden ist die Seite ganz offen; eine kleinere Öffnung lässt die Ecken der Seite und den Stapelrand daneben stehen.",
  "prop.gridfinityOpeningCorner": "Ecken der Öffnung",
  "prop.gridfinityOpeningCornerSize": "Größe der Öffnungsecken",
  "gridfinity.openingCornerHint": "Die oberen und unteren Ecken der Öffnungen, von außen auf die Wand gesehen; unter 0,5 mm bleiben sie rechtwinklig. Eine Öffnung über die ganze Seite hat oben keine Ecken.",
  "prop.gridfinityPaddingBack": "Ausgleich hinten",
  "prop.gridfinityPaddingFront": "Ausgleich vorne",
  "prop.gridfinityPaddingLeft": "Ausgleich links",
  "prop.gridfinityPaddingRight": "Ausgleich rechts",
  "gridfinity.paddingHint": "Ein massiver Streifen außerhalb des Rasters, damit die Bodenplatte eine Schublade füllt, die keine ganze Zahl von Einheiten misst. Ändert er sich, bleiben die Einheiten, und die Größe der Platte ändert sich mit.",
  "prop.gridfinityCornerRadius": "Eckenradius",
  "gridfinity.cornerRadiusHint": "Der Radius der vier äußeren Ecken der Platte, von 4 mm, wie die Gridfinity-Spezifikation sie zeichnet, bis 0 für rechtwinklige Ecken, die in die Ecken einer Schublade passen. Die Mulden behalten ihre Rundung, die Behälter passen also wie bisher.",
  "gridfinity.binCornerRadiusHint": "Der Radius der äußeren Ecken des Behälters über den Füßen: von 3,75 mm, wie die Gridfinity-Spezifikation sie zeichnet, bis 0 für rechtwinklige Ecken, damit nebeneinanderstehende Behälter in einer Schublade auch dort, wo vier zusammentreffen, nur ihre 0,5-mm-Spalten lassen. Die Füße, das Innere und die Schrägen des Stapelrands, auf denen ein gestapelter Behälter steht, behalten ihre Rundung; der Behälter sitzt also in einer Bodenplatte und lässt sich stapeln wie bisher.",
  "prop.gridfinityDrawerWidth": "Schubladenbreite",
  "prop.gridfinityDrawerDepth": "Schubladentiefe",
  "gridfinity.drawerHint": "Das Innenmaß der Schublade; die Platte wird 0,5 mm kleiner. Eine Schublade größer als 334,5 mm oder als dein Druckbett braucht mehrere Bodenplatten.",
