  "export.stl.description": "Netz für den 3D-Druck",
  "export.stl.note": "Am besten für Slicer und 3D-Druck. Die Geometrie wird als Dreiecksnetz ausgegeben. In Chrome und Edge wählst du Ordner und Namen einmal; weitere STL-Exporte des Entwurfs schreiben in diese Datei, außer du tippst einen anderen Namen: dann wirst du erneut gefragt.",
