  "export.stlSaveAs": "Speichern unter …",
  "export.3mf.description": "Slicer-Datei mit Farben",
  "export.3mf.note": "Für PrusaSlicer, Bambu Studio, OrcaSlicer und Cura. Jeder Körper bleibt ein eigenes Teil mit Namen und Farbe.",
  "export.obj.description": "Universelles 3D-Netz",
  "export.obj.note": "Ein breit unterstütztes Netzformat für Modellierung, Bildberechnung und Austausch. Die Farben stehen an den Eckpunkten, Bambu Studio und OrcaSlicer lesen sie.",
  "export.step.description": "CAD / B-Rep",
  "export.step.note": "Behält Quader, Zylinder, Kugeln und Kegel als exakte CAD-Geometrie, dazu alles mit verrundeten oder gefasten Kanten und Körper, die als STEP hereingekommen sind. Gewinde, Federn und Zahnräder gehen ebenfalls als exakter Körper. Verjüngte, geneigte und verdrehte Formen gehen exakt mit. Eingelesene Netze zum Beispiel kann STEP nicht tragen — die gehen als STL.",
  "export.svg.description": "Vektor-Draufsicht",
  "export.svg.note": "Gibt eine saubere Draufsicht in Millimetern aus, samt Löchern und gekrümmten Umrissen.",
  "export.svg.noteFootprint": "Gibt nur die Umrisse aus, mit denen die Objekte auf der Arbeitsebene stehen, als Linien in Millimetern, für Laser und Schablonen.",
  "export.svg.noteEdges": "Gibt die von oben sichtbaren Kanten als Linien in Millimetern aus, jeden Körper in seiner Farbe: Umrisse, Löcher, Taschen und Gravuren, jede Fläche geschlossen, für Lasergravur und Plotter.",
  "export.svg.view": "Ansicht",
  "export.svg.viewSilhouette": "Silhouette von oben",
  "export.svg.viewFootprint": "Aufstandsfläche auf der Arbeitsebene",
  "export.bridges": "Stege für herausfallende Teile",
  "export.bridgesHint": "Ein Teil innerhalb eines Ausschnitts (die Mitte eines „o“, der Bauch eines „b“) fällt heraus, wenn es rundum geschnitten wird. Kleine Stege halten es an seinem Platz, wie bei einer Schablone.",
  "export.bridgeWidth": "Stegbreite",
  "export.bridgeCount": "Stege pro Teil",
  "export.svg.viewEdges": "Sichtbare Kanten von oben",
  "export.dxf.description": "Umriss für Laserschnitt",
  "export.dxf.note": "Gibt den Umriss von oben für Laserschneid-Betriebe aus: Linien, echte Bögen und Kreise auf Layer 0 in Weiß, in Millimetern. Körper, die sich berühren, werden ein Umriss.",
  "export.dxf.noteFootprint": "Gibt nur die Umrisse aus, mit denen die Objekte auf der Arbeitsebene stehen, für Laserschneid-Betriebe: Linien, echte Bögen und Kreise auf Layer 0 in Weiß, in Millimetern.",
  "export.lyl.description": "layerlings eigenes Entwurfsformat",
  "export.lyl.note": "Bewahrt den bearbeitbaren Entwurf, den Verlauf, Skizzen, Gruppen, CAD-Daten und importierte Quellen. Ältere .skf-Dateien lassen sich weiterhin öffnen und werden als .lyl gesichert. In Chrome und Edge wählst du Ordner und Namen selbst, und Strg+S speichert danach wieder in diese Datei; ein aus einer Datei geöffneter Entwurf wird in sie zurückgespeichert.",
  "import.openProject": "layerling-Entwurf öffnen",
